use crate::dynamic_asset::{DynamicAsset, DynamicAssetType, DynamicAssets, MissingDynamicAsset};
use crate::mapped::MapKey;

// The generated code names Bevy types through these re-exports
pub use bevy_asset;
pub use bevy_ecs;
#[cfg(any(feature = "2d", feature = "3d"))]
pub use bevy_image;
#[cfg(feature = "2d")]
pub use bevy_math;
#[cfg(feature = "3d")]
pub use bevy_pbr;
pub use bevy_platform;

/// A collection field type that holds handles of a single asset type.
pub trait TypedHandleField {
    /// The asset type behind the field's handles.
    type Asset: Asset;
}

impl<A: Asset> TypedHandleField for Handle<A> {
    type Asset = A;
}

impl<T: TypedHandleField> TypedHandleField for Option<T> {
    type Asset = T::Asset;
}

impl<A: Asset> TypedHandleField for Vec<Handle<A>> {
    type Asset = A;
}

impl<K, A: Asset, S> TypedHandleField for HashMap<K, Handle<A>, S> {
    type Asset = A;
}

impl<K, A: Asset, S> TypedHandleField for HashMap<K, Vec<Handle<A>>, S> {
    type Asset = A;
}

/// The value type of a mapped asset collection field built from a [`DynamicAssetType::Map`]
pub trait MapValue: Sized {
    /// Description of the accepted values for error messages
    const EXPECTED: &'static str;

    /// Convert a value of a dynamic asset map, or give it back if it does not fit this type.
    fn from_dynamic_asset_type(value: DynamicAssetType) -> Result<Self, DynamicAssetType>;
}

impl<A: Asset> MapValue for Handle<A> {
    const EXPECTED: &'static str = "a single handle";

    fn from_dynamic_asset_type(value: DynamicAssetType) -> Result<Self, DynamicAssetType> {
        match value {
            DynamicAssetType::Single(handle) => Ok(handle.typed()),
            value => Err(value),
        }
    }
}

impl MapValue for UntypedHandle {
    const EXPECTED: &'static str = "a single handle";

    fn from_dynamic_asset_type(value: DynamicAssetType) -> Result<Self, DynamicAssetType> {
        match value {
            DynamicAssetType::Single(handle) => Ok(handle),
            value => Err(value),
        }
    }
}

impl<A: Asset> MapValue for Vec<Handle<A>> {
    const EXPECTED: &'static str = "any number of handles";

    fn from_dynamic_asset_type(value: DynamicAssetType) -> Result<Self, DynamicAssetType> {
        Ok(value
            .into_handles()
            .into_iter()
            .map(|handle| handle.typed())
            .collect())
    }
}

impl MapValue for Vec<UntypedHandle> {
    const EXPECTED: &'static str = "any number of handles";

    fn from_dynamic_asset_type(value: DynamicAssetType) -> Result<Self, DynamicAssetType> {
        Ok(value.into_handles())
    }
}

/// A field of an asset collection that is filled from a dynamic asset.
pub struct DynamicField {
    collection: &'static str,
    field: &'static str,
    key: &'static str,
}

/// The kind of value an asset collection field expects a dynamic asset to resolve to
#[derive(Clone, Copy)]
enum Expected {
    Single,
    List,
    Map,
}

impl DynamicField {
    /// Describe the field `field` of the asset collection `C` with the dynamic asset key `key`
    pub fn new<C>(field: &'static str, key: &'static str) -> Self {
        let collection = type_name::<C>();
        Self {
            collection: collection.rsplit("::").next().unwrap_or(collection),
            field,
            key,
        }
    }

    /// Get the dynamic asset for this field
    ///
    /// # Panics
    ///
    /// If the key is not known
    pub fn get<'a>(&self, dynamic_assets: &'a DynamicAssets) -> &'a dyn DynamicAsset {
        dynamic_assets
            .resolve(self.key)
            .unwrap_or_else(|missing| match missing {
                MissingDynamicAsset::Key(key) => panic!(
                    "{}: there is no dynamic asset with the key '{key}'. \
                    Check the keys in your dynamic asset files, or register the key with `DynamicAssets`.",
                    self.prefix(),
                ),
                MissingDynamicAsset::Entry { parent, entry } => panic!(
                    "{}: the dynamic asset '{parent}' has no entry '{entry}'. \
                    Only maps and arrays in dynamic asset files have entries, addressed by key or index.",
                    self.prefix(),
                ),
            })
    }

    /// Unwrap the result of building the dynamic asset for this field
    ///
    /// # Panics
    ///
    /// If building the dynamic asset failed
    pub fn built(&self, result: Result<DynamicAssetType, anyhow::Error>) -> DynamicAssetType {
        result.unwrap_or_else(|error| {
            panic!(
                "{}: building the dynamic asset '{}' failed: {error:#}",
                self.prefix(),
                self.key
            )
        })
    }

    /// The handle of a dynamic asset for a field holding a single handle
    ///
    /// # Panics
    ///
    /// If the dynamic asset does not resolve to a single handle
    pub fn single(&self, value: DynamicAssetType) -> UntypedHandle {
        match value {
            DynamicAssetType::Single(handle) => handle,
            value => self.mismatch(Expected::Single, &value),
        }
    }

    /// The handles of a dynamic asset for a field holding a list of handles
    ///
    /// # Panics
    ///
    /// If the dynamic asset does not resolve to a list of handles
    pub fn list(&self, value: DynamicAssetType) -> Vec<UntypedHandle> {
        match value {
            DynamicAssetType::Collection(handles) => handles,
            value => self.mismatch(Expected::List, &value),
        }
    }

    /// The value of a mapped field
    ///
    /// For a list of handles, the keys
    /// are derived from the asset paths.
    ///
    /// # Panics
    ///
    /// If the dynamic asset does not resolve to a map or a list of handles, or a value does not
    /// fit the value type of the field
    pub fn map<K: MapKey, V: MapValue, T: FromIterator<(K, V)>>(
        &self,
        value: DynamicAssetType,
    ) -> T {
        match value {
            DynamicAssetType::Collection(handles) => handles
                .into_iter()
                .map(|handle| {
                    let path = handle.path().unwrap_or_else(|| {
                        panic!(
                            "{}: the dynamic asset '{}' contains a handle without an asset path, so no map key can be derived for it. \
                            Define a map in your dynamic asset file to choose the keys yourself.",
                            self.prefix(),
                            self.key
                        )
                    });
                    let key = K::from_asset_path(path);
                    let value = V::from_dynamic_asset_type(DynamicAssetType::Single(handle))
                        .unwrap_or_else(|_| unreachable!("every map value type accepts a single handle"));
                    (key, value)
                })
                .collect(),
            DynamicAssetType::Map(map) => map
                .into_iter()
                .map(|(key, value)| {
                    let value = V::from_dynamic_asset_type(value).unwrap_or_else(|value| {
                        panic!(
                            "{}: the entry '{key}' of the dynamic asset '{}' is {}, but the field expects {} per key. \
                            Use `Vec<Handle<T>>` or `Vec<UntypedHandle>` as value type to allow any number of handles per key.",
                            self.prefix(),
                            self.key,
                            describe(&value),
                            V::EXPECTED
                        )
                    });
                    (K::from_dynamic_key(&key), value)
                })
                .collect(),
            value => self.mismatch(Expected::Map, &value),
        }
    }

    fn prefix(&self) -> String {
        format!(
            "Cannot load the field `{}` of the asset collection {}",
            self.field, self.collection
        )
    }

    fn mismatch(&self, expected: Expected, value: &DynamicAssetType) -> ! {
        let expects = match expected {
            Expected::Single => "a single handle",
            Expected::List => "a list of handles",
            Expected::Map => "a map of handles",
        };
        let hint = match (expected, value) {
            (Expected::Single, DynamicAssetType::Collection(_)) => {
                "Use a `Vec` field with `#[asset(key = \"..\", collection)]` to hold all of them."
            }
            (Expected::Single | Expected::List, DynamicAssetType::Map(map)) => {
                let example = map.keys().min().map_or("..", String::as_str);
                &format!(
                    "Use a `HashMap` field with `#[asset(key = \"{key}\", collection(mapped))]` to keep the keys, \
                    or load a single entry with `#[asset(key = \"{key}[{example}]\")]`.",
                    key = self.key
                )
            }
            (Expected::List | Expected::Map, DynamicAssetType::Single(_)) => {
                "Use a `Handle` field without `collection`, or define an array of dynamic assets for the key."
            }
            _ => "",
        };
        let message = format!(
            "{}: the field expects {expects}, but the dynamic asset '{}' is {}. {hint}",
            self.prefix(),
            self.key,
            describe(value)
        );
        panic!("{}", message.trim_end())
    }
}

fn describe(value: &DynamicAssetType) -> String {
    const SHOWN_ENTRIES: usize = 5;
    match value {
        DynamicAssetType::Single(_) => "a single handle".to_owned(),
        DynamicAssetType::Collection(handles) => {
            format!("a list of {} handles", handles.len())
        }
        DynamicAssetType::Map(map) => {
            let mut keys: Vec<_> = map.keys().map(String::as_str).collect();
            keys.sort_unstable();
            let mut shown = keys
                .iter()
                .take(SHOWN_ENTRIES)
                .copied()
                .collect::<Vec<_>>()
                .join(", ");
            if keys.len() > SHOWN_ENTRIES {
                shown.push_str(", ...");
            }
            format!("a map with {} entries ({shown})", map.len())
        }
    }
}

/// Loading of an asset collection field failed, because the field's asset type is not
/// registered with the app.
#[derive(Debug)]
pub struct UnregisteredAssetType {
    collection: &'static str,
    field: &'static str,
    asset_type: &'static str,
}

impl UnregisteredAssetType {
    fn of_field<C, F: TypedHandleField>(field: &'static str) -> Self {
        let collection = type_name::<C>();
        let collection = collection.rsplit("::").next().unwrap_or(collection);
        Self {
            collection,
            field,
            asset_type: F::Asset::short_type_path(),
        }
    }
}

impl fmt::Display for UnregisteredAssetType {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let Self {
            collection,
            field,
            asset_type,
        } = self;
        write!(
            f,
            "Asset collection field `{collection}::{field}` holds handles of `{asset_type}`, \
            but that asset type is not registered with the app. \
            Add the plugin that provides it or call `app.init_asset::<{asset_type}>()`."
        )
    }
}

impl Error for UnregisteredAssetType {}

/// The asset type of the field `field` points to, or a handle that fails to load with an
/// [`UnregisteredAssetType`] error if that type is not registered.
fn registered_asset_type<C, F: TypedHandleField>(
    world: &World,
    field_name: &'static str,
) -> Result<TypeId, UntypedHandle> {
    if world.contains_resource::<Assets<F::Asset>>() {
        return Ok(TypeId::of::<F::Asset>());
    }
    let error = UnregisteredAssetType::of_field::<C, F>(field_name);
    let failing = world
        .resource::<AssetServer>()
        .add_async::<LoadedFolder, _>(async move { Err(error) });
    Err(failing.untyped())
}

/// The asset type of the field `field` points to, while creating the collection.
///
/// # Panics
/// If the asset type is not registered. With a loading state, the collection is only created
/// after all fields loaded, which requires the asset types to be registered.
pub fn asset_type_of_field<C, F: TypedHandleField>(
    world: &World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
) -> TypeId {
    if !world.contains_resource::<Assets<F::Asset>>() {
        panic!("{}", UnregisteredAssetType::of_field::<C, F>(field_name));
    }
    TypeId::of::<F::Asset>()
}

/// Load `paths` as the asset type of the field `field` points to.
pub fn load_paths<C, F: TypedHandleField>(
    world: &World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
    paths: &[&'static str],
) -> Vec<UntypedHandle> {
    if let Err(failing) = registered_asset_type::<C, F>(world, field_name) {
        return vec![failing];
    }
    let asset_server = world.resource::<AssetServer>();
    paths
        .iter()
        .map(|path| asset_server.load::<F::Asset>(*path).untyped())
        .collect()
}

/// Load a dynamic asset as the asset type of the field `field` points to.
pub fn load_dynamic<C, F: TypedHandleField>(
    world: &mut World,
    asset: &dyn DynamicAsset,
    _field: fn(&C) -> &F,
    field_name: &'static str,
) -> Vec<UntypedHandle> {
    match registered_asset_type::<C, F>(world, field_name) {
        Ok(asset_type) => asset.load_as(world, asset_type),
        Err(failing) => vec![failing],
    }
}

/// Build a dynamic asset loaded with [`load_dynamic`].
pub fn build_dynamic(
    asset: &dyn DynamicAsset,
    asset_type: TypeId,
    world: &mut World,
) -> Result<DynamicAssetType, anyhow::Error> {
    asset.build_as(world, asset_type)
}

/// Load a folder as the asset type of the field `field` points to.
pub fn load_folder<C, F: TypedHandleField>(
    world: &mut World,
    _field: fn(&C) -> &F,
    field_name: &'static str,
    path: &'static str,
) -> UntypedHandle {
    match registered_asset_type::<C, F>(world, field_name) {
        Ok(asset_type) => crate::typed_folder::load_folder_as(world, path, asset_type).untyped(),
        Err(failing) => failing,
    }
}

/// The handle of a folder loaded with [`load_folder`].
pub fn folder_handle<'a>(
    world: &World,
    path: impl Into<AssetPath<'a>>,
    asset_type: TypeId,
) -> Option<Handle<LoadedFolder>> {
    crate::typed_folder::get_folder_as(world, path, asset_type)
}

#[cfg(test)]
mod tests {
    use super::*;

    struct MyAssets;

    fn field() -> DynamicField {
        DynamicField::new::<MyAssets>("layouts", "named")
    }

    fn handle() -> UntypedHandle {
        Handle::<LoadedFolder>::default().untyped()
    }

    fn map(keys: &[&str]) -> DynamicAssetType {
        DynamicAssetType::Map(
            keys.iter()
                .map(|key| (key.to_string(), DynamicAssetType::Single(handle())))
                .collect(),
        )
    }

    fn panic_message(f: impl FnOnce() + std::panic::UnwindSafe) -> String {
        let payload = std::panic::catch_unwind(f).unwrap_err();
        payload
            .downcast_ref::<String>()
            .cloned()
            .unwrap_or_else(|| payload.downcast_ref::<&str>().unwrap().to_string())
    }

    #[test]
    fn list_field_on_map() {
        assert_eq!(
            panic_message(|| {
                field().list(map(&["walk", "idle"]));
            }),
            "Cannot load the field `layouts` of the asset collection MyAssets: the field expects a list of handles, \
            but the dynamic asset 'named' is a map with 2 entries (idle, walk). \
            Use a `HashMap` field with `#[asset(key = \"named\", collection(mapped))]` to keep the keys, \
            or load a single entry with `#[asset(key = \"named[idle]\")]`."
        );
    }

    #[test]
    fn single_field_on_list() {
        assert_eq!(
            panic_message(|| {
                field().single(DynamicAssetType::Collection(vec![handle(), handle()]));
            }),
            "Cannot load the field `layouts` of the asset collection MyAssets: the field expects a single handle, \
            but the dynamic asset 'named' is a list of 2 handles. \
            Use a `Vec` field with `#[asset(key = \"..\", collection)]` to hold all of them."
        );
    }

    #[test]
    fn mapped_field_on_single() {
        assert_eq!(
            panic_message(|| {
                let _: HashMap<String, UntypedHandle> =
                    field().map(DynamicAssetType::Single(handle()));
            }),
            "Cannot load the field `layouts` of the asset collection MyAssets: the field expects a map of handles, \
            but the dynamic asset 'named' is a single handle. \
            Use a `Handle` field without `collection`, or define an array of dynamic assets for the key."
        );
    }

    #[test]
    fn long_maps_are_shortened() {
        assert_eq!(
            describe(&map(&["g", "f", "e", "d", "c", "b", "a"])),
            "a map with 7 entries (a, b, c, d, e, ...)"
        );
    }

    #[test]
    fn missing_key() {
        assert_eq!(
            panic_message(|| {
                field().get(&DynamicAssets::default());
            }),
            "Cannot load the field `layouts` of the asset collection MyAssets: there is no dynamic asset with the key 'named'. \
            Check the keys in your dynamic asset files, or register the key with `DynamicAssets`."
        );
    }

    #[test]
    fn build_error() {
        assert_eq!(
            panic_message(|| {
                field().built(Err(
                    anyhow::anyhow!("file not found").context("loading failed")
                ));
            }),
            "Cannot load the field `layouts` of the asset collection MyAssets: building the dynamic asset 'named' failed: loading failed: file not found"
        );
    }
}
